import{storage}from'../core/storage.js';import{money}from'../core/format.js';import{loadProducts}from'../core/api.js';import{toast}from'./toast.js';let cart=storage.get('serioes-cart-v2',[]),products=[];export async function initCart(){products=await loadProducts();render();document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){cart.push(add.dataset.add);save();toast('FEHLENTSCHEIDUNG HINZUGEFÜGT ✓')}if(e.target.closest('[data-cart]'))open();if(e.target.closest('[data-cart-close]')||e.target.matches('[data-backdrop]'))close();const del=e.target.closest('[data-remove]');if(del){cart.splice(Number(del.dataset.remove),1);save()}})}function save(){storage.set('serioes-cart-v2',cart);render()}function open(){document.querySelector('[data-cart-drawer]')?.classList.add('open');document.querySelector('[data-backdrop]')?.classList.add('open')}function close(){document.querySelector('[data-cart-drawer]')?.classList.remove('open');document.querySelector('[data-backdrop]')?.classList.remove('open')}function render(){document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=cart.length);const list=document.querySelector('[data-cart-items]'),empty=document.querySelector('[data-cart-empty]');if(!list)return;empty.style.display=cart.length?'none':'block';list.innerHTML=cart.map((slug,i)=>{const p=products.find(x=>x.slug===slug);return p?`<div class="cart-row"><div class="cart-glyph">${p.glyph}</div><div><h4>${p.name}</h4><span>${money(p.price)}</span></div><button data-remove="${i}">ENTFERNEN</button></div>`:''}).join('');const total=cart.reduce((s,slug)=>s+(products.find(p=>p.slug===slug)?.price||0),0);document.querySelector('[data-cart-total]').textContent=money(total)}export const cartItems=()=>cart;
